@namespace sv_117923a2ce154e43a83e6ae741e9313d.Components.Application

<nav class="step-indicator">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var cssClass = GetStepClass(stepIndex);
        <button class="step @cssClass"
                disabled="@(!IsStepClickable(stepIndex))"
                @onclick="() => OnStepClicked(stepIndex)">
            <span class="step-number">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (i < StepNames.Count - 1)
        {
            <span class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private bool IsStepClickable(int index) => index < CurrentStep;

    private Task OnStepClicked(int index)
    {
        if (IsStepClickable(index))
            return OnNavigateToStep.InvokeAsync(index);
        return Task.CompletedTask;
    }
}

