@page "/apply"
@rendermode InteractiveServer
@using sv_117923a2ce154e43a83e6ae741e9313d.Components.Application
@using sv_117923a2ce154e43a83e6ae741e9313d.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName"
                              Email="@email"
                              Phone="@phone"
                              Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep FullName="@fullName"
                        Email="@email"
                        Phone="@phone"
                        Address="@address"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEditStep="NavigateToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private readonly List<string> stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new()
    {
        new("", "", DateTime.Today, null, "")
    };

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new()
    {
        new("", "", "", ""),
        new("", "", "", "")
    };

    // Step 4 state
    private string coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private void GoBack() => currentStep--;

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        fullName = data.FullName;
        email = data.Email;
        phone = data.Phone;
        address = data.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(fullName, email, phone, address),
            new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

